"""Hashtags are supplied by the user, never generated by the model."""
import re
import unicodedata


def normalize_hashtags(value):
    if not isinstance(value,str) or len(value)>1000:
        raise ValueError('Hashtag tối đa 1.000 ký tự.')
    tags=[]
    seen=set()
    for token in re.split(r'[\s,;]+',unicodedata.normalize('NFC',value.strip())):
        if not token:
            continue
        tag=token if token.startswith('#') else '#'+token
        if not re.fullmatch(r'#[\w]+',tag):
            raise ValueError('Hashtag chỉ gồm chữ, số và dấu gạch dưới; tách bằng khoảng trắng hoặc dấu phẩy.')
        if tag.casefold() not in seen:
            tags.append(tag); seen.add(tag.casefold())
    result=' '.join(tags)
    if len(result)>1000:
        raise ValueError('Hashtag tối đa 1.000 ký tự.')
    return result


def without_hashtags(text):
    text=re.sub(r'(?<!\w)[#＃][\w\u0300-\u036f]+','',text)
    text=re.sub(r'[ \t]+',' ',text)
    text=re.sub(r' *\n *','\n',text)
    return re.sub(r'\n{3,}','\n\n',text).strip()


def finish_caption(text,hashtags):
    clean=without_hashtags(text)
    if not clean:
        raise ValueError('AI không trả về nội dung caption ngoài hashtag.')
    result=clean+('\n\n'+hashtags if hashtags else '')
    if len(result)>10000:
        raise ValueError('Caption kèm hashtag vượt 10.000 ký tự.')
    return result
